import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        int n = in.readInt();
        int ans = new Solver().solve(n);
        out.print(ans);
        out.close();
    }

    static class Solver {
        static final int MOD = (int) 1e9 + 7;

        int solve(int n) {
            int[][][] dp = new int[2 * n + 1][2 * n + 1][2];
            dp[0][0][0] = 1;
            for (int depth = 1; depth <= 2 * n; depth++) {
                for (int opened = depth & 1; opened <= depth; opened += 2) {
                    int fromPrev0 = 0, fromPrev1 = 0;
                    if (opened - 1 >= 0) {
                        fromPrev0 += dp[depth - 1][opened - 1][1];
                        fromPrev1 += dp[depth - 1][opened - 1][0];
                    }
                    if (opened + 1 <= n) {
                        fromPrev0 += dp[depth - 1][opened + 1][1];
                        fromPrev1 += dp[depth - 1][opened + 1][0];
                    }
                    dp[depth][opened][0] = (fromPrev0 + 1) % MOD;
                    dp[depth][opened][1] = fromPrev1 % MOD;
                }
            }
            return dp[2 * n][0][1];
        }
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (Exception e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') { sgn = -1; c = read(); }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
